# WellNest 25-deck series content. Each pair: (group, ask, A, B); option = (label, desc, kind?, arg?)
# kinds: tag quote offer ig web pal av pk ph dash ty. Default kind per deck.
from wn_series_kit import *
D = []
def deck(cat, order, name, slug, dk, about, pairs): D.append(dict(cat=cat, order=order, name=name, slug=slug, dk=dk, about=about, pairs=pairs))
AV = {1: "Fine Threads With Tails", 2: "Four Bold Loops", 3: "Loops With A Sprout", 4: "Nest Bowl With Eggs", 5: "Loops On A Cream Tile"}
def av(k, extra="", **kw): return (AV[k] + (", " + extra if extra else ""), f"Option {k}" + (f": {extra.lower()}" if extra else ""), "av", dict(k=k, **kw))

